using Microsoft.EntityFrameworkCore;

static async Task<IResult> SignUp(SignUpRequest req, AppDb db)
{
    // Check, then insert: two concurrent requests both pass the check
    if (await db.Users.AnyAsync(u => u.Email == req.Email))
        return Results.Conflict("Email already registered");

    db.Users.Add(new User { Email = req.Email });
    await db.SaveChangesAsync(); // SQL test: both inserts succeeded
    return Results.Created();
}

using Microsoft.Data.SqlClient;
using Microsoft.EntityFrameworkCore;

static async Task<IResult> SignUp(SignUpRequest req, AppDb db)
{
    // The check gives a friendly message; the unique index is the guarantee
    if (await db.Users.AnyAsync(u => u.Email == req.Email))
        return Results.Conflict("Email already registered");

    db.Users.Add(new User { Email = req.Email });
    try { await db.SaveChangesAsync(); }
    catch (DbUpdateException e) when (e.InnerException is SqlException
        { Number: 2601 or 2627 }) // unique index or UNIQUE constraint
    {
        return Results.Conflict("Email already registered");
    }
    return Results.Created();
}

